import pandas as pd
import numpy as np

# Load data
energy_data = pd.read_csv('chunks_csv/moran_local_2023_energy.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute neighborhood energy consumption
neighborhood_energy = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhood_energy:
        neighborhood_energy[borough] = []
    if neighbor not in neighborhood_energy[borough]:
        neighborhood_energy[borough].append(energy_data.loc[energy_data['borough'] == neighbor, 'Energy_value'].values[0])

# Compute average neighborhood energy consumption
neighborhood_energy_avg = {}
for borough, neighbors in neighborhood_energy.items():
    neighborhood_energy_avg[borough] = np.mean(neighbors)

# Identify hot and cold spots
hot_cold_spots = {}
for index, row in energy_data.iterrows():
    borough = row['borough']
    energy_value = row['Energy_value']
    if energy_value > neighborhood_energy_avg[borough]:
        hot_cold_spots[borough] = 'HH'
    elif energy_value < neighborhood_energy_avg[borough]:
        hot_cold_spots[borough] = 'LL'

# Apply Moran's I test
def moran_i_test(data, weights):
    n = len(data)
    mean = np.mean(data)
    variance = np.var(data)
    numerator = np.sum(weights * (data - mean) ** 2)
    denominator = n * variance
    return numerator / denominator

# Compute statistical method value
statistical_method_values = {}
for borough, hot_cold in hot_cold_spots.items():
    if hot_cold == 'HH':
        data = energy_data.loc[energy_data['borough'] == borough, 'Energy_value'].values
        weights = [1 if neighbor in neighborhood_energy[borough] else 0 for neighbor in neighborhood_energy[borough]]
        statistical_method_values[borough] = moran_i_test(data, weights)
    elif hot_cold == 'LL':
        data = energy_data.loc[energy_data['borough'] == borough, 'Energy_value'].values
        weights = [1 if neighbor in neighborhood_energy[borough] else 0 for neighbor in neighborhood_energy[borough]]
        statistical_method_values[borough] = moran_i_test(data, weights)

# List identified boroughs
data_points_used = len(energy_data)
final_answer = []
for borough, hot_cold in hot_cold_spots.items():
    if hot_cold == 'HH':
        final_answer.append(f'{borough} (HH, statistical method={statistical_method_values[borough]})')
    elif hot_cold == 'LL':
        final_answer.append(f'{borough} (LL, statistical method={statistical_method_values[borough]})')

print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {" , ".join(final_answer)}')
